mapper.select:
select date_format(create_time, '%Y-%m') as label, count(*) as cnt from clue where create_time >= date_format(date_sub(curdate(), interval #{months} month), '%Y-%m-01')
and user_id = #{scopeUserId}
group by label

select date_format(create_time, '%Y-%m') as label, count(*) as cnt from business where create_time >= date_format(date_sub(curdate(), interval #{months} month), '%Y-%m-01')
and user_id = #{scopeUserId}
group by label

select ifnull(channel, -1) as label, count(*) as cnt from clue
user_id = #{scopeUserId}
group by label

select ifnull(status, -1) as label, count(*) as cnt from clue
user_id = #{scopeUserId}
group by label
